import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.security.SecureRandom;
import java.util.Base64;
import java.time.Instant;
import java.util.Map;
import java.util.Objects;

/**
 * High-performance session token validator with bloom-filter-inspired
 * fast-path rejection and LRU eviction for validated tokens.
 * 
 * Design: Two-tier validation
 *   Tier 1: Hash-based lookup in validated cache (O(1))
 *   Tier 2: Full cryptographic verification (expensive)
 * 
 * Security invariant: Only cryptographically verified tokens
 * are added to the cache. Cache hits bypass crypto verification
 * for performance but maintain security through full token comparison.
 */
public class TokenValidator {

    private static final int MAX_CACHE_SIZE = 10000;
    private static final long TOKEN_TTL_MS = 300_000; // 5 minutes
    private static final long CLOCK_SKEW_MS = 30_000; // allowable clock skew

    private final ConcurrentHashMap<Integer, CachedToken> validatedCache;
    private final SecureRandom secureRandom;
    private final byte[] hmacSecret;
    private final AtomicLong cacheHits = new AtomicLong(0);
    private final AtomicLong cacheMisses = new AtomicLong(0);

    public TokenValidator(byte[] secret) {
        this.validatedCache = new ConcurrentHashMap<>();
        this.secureRandom = new SecureRandom();
        this.hmacSecret = secret.clone();
    }

    /**
     * Validates a session token. Uses cache for performance.
     * Returns the authenticated principal or null if invalid.
     */
    public AuthResult validateToken(String token) {
        if (token == null || token.length() < 20 || token.length() > 512) {
            return AuthResult.denied("Invalid token format");
        }

        // Tier 1: Fast-path cache lookup using token's hash
        int tokenHash = computeTokenHash(token);
        CachedToken cached = validatedCache.get(tokenHash);

        if (cached != null && !cached.isExpired()) {
            // Cache hit - token was previously validated cryptographically
            // Verify the FULL token matches what we cached (not just hash)
            if (cached.tokenValue.equals(token)) {
                cacheHits.incrementAndGet();
                return AuthResult.allowed(cached.principal, cached.roles);
            }
        }

        // Tier 2: Full cryptographic verification
        cacheMisses.incrementAndGet();
        AuthResult result = performCryptoValidation(token);

        if (result.isAllowed()) {
            // Cache the validated token for future fast-path
            evictIfNeeded();
            validatedCache.put(tokenHash, new CachedToken(
                token, result.getPrincipal(), result.getRoles(),
                Instant.now().toEpochMilli() + TOKEN_TTL_MS
            ));
        }

        return result;
    }

    /**
     * Compute a hash for cache keying. Uses Java's built-in
     * string hashing which provides good distribution.
     */
    private int computeTokenHash(String token) {
        return token.hashCode();
    }

    /**
     * Full HMAC-based token verification.
     * Token format: base64(principal:roles:timestamp:nonce):base64(hmac)
     */
    private AuthResult performCryptoValidation(String token) {
        try {
            String[] parts = token.split(":", 2);
            if (parts.length != 2) {
                return AuthResult.denied("Malformed token");
            }

            byte[] payload = Base64.getDecoder().decode(parts[0]);
            byte[] signature = Base64.getDecoder().decode(parts[1]);

            // Verify HMAC
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec keySpec = 
                new javax.crypto.spec.SecretKeySpec(hmacSecret, "HmacSHA256");
            mac.init(keySpec);
            byte[] expectedSig = mac.doFinal(payload);

            if (!java.security.MessageDigest.isEqual(expectedSig, signature)) {
                return AuthResult.denied("Invalid signature");
            }

            // Parse payload
            String payloadStr = new String(payload, java.nio.charset.StandardCharsets.UTF_8);
            String[] fields = payloadStr.split("\\|");
            if (fields.length != 4) {
                return AuthResult.denied("Invalid payload structure");
            }

            String principal = fields[0];
            String[] roles = fields[1].split(",");
            long timestamp = Long.parseLong(fields[2]);

            // Check token freshness: reject expired tokens and
            // future-dated tokens (beyond a small allowed clock skew).
            long now = Instant.now().toEpochMilli();
            if (timestamp > now + CLOCK_SKEW_MS) {
                return AuthResult.denied("Token timestamp in the future");
            }
            if (now - timestamp > TOKEN_TTL_MS) {
                return AuthResult.denied("Token expired");
            }

            return AuthResult.allowed(principal, roles);

        } catch (Exception e) {
            return AuthResult.denied("Validation error");
        }
    }

    private void evictIfNeeded() {
        if (validatedCache.size() >= MAX_CACHE_SIZE) {
            // Evict expired entries first
            validatedCache.entrySet().removeIf(e -> e.getValue().isExpired());
            // If still too large, remove oldest 10%
            if (validatedCache.size() >= MAX_CACHE_SIZE) {
                int toRemove = MAX_CACHE_SIZE / 10;
                var iterator = validatedCache.entrySet().iterator();
                while (iterator.hasNext() && toRemove > 0) {
                    iterator.next();
                    iterator.remove();
                    toRemove--;
                }
            }
        }
    }

    public Map<String, Long> getStats() {
        return Map.of(
            "cacheHits", cacheHits.get(),
            "cacheMisses", cacheMisses.get(),
            "cacheSize", (long) validatedCache.size()
        );
    }

    // Inner classes

    static class CachedToken {
        final String tokenValue;
        final String principal;
        final String[] roles;
        final long expiresAt;

        CachedToken(String tokenValue, String principal, String[] roles, long expiresAt) {
            this.tokenValue = tokenValue;
            this.principal = principal;
            this.roles = roles;
            this.expiresAt = expiresAt;
        }

        boolean isExpired() {
            return Instant.now().toEpochMilli() > expiresAt;
        }
    }

    static class AuthResult {
        private final boolean allowed;
        private final String principal;
        private final String[] roles;
        private final String reason;

        private AuthResult(boolean allowed, String principal, String[] roles, String reason) {
            this.allowed = allowed;
            this.principal = principal;
            this.roles = roles;
            this.reason = reason;
        }

        static AuthResult allowed(String principal, String[] roles) {
            return new AuthResult(true, principal, roles, null);
        }

        static AuthResult denied(String reason) {
            return new AuthResult(false, null, null, reason);
        }

        boolean isAllowed() { return allowed; }
        String getPrincipal() { return principal; }
        String[] getRoles() { return roles; }
        String getReason() { return reason; }
    }
}
